package calc

// 0x5a6340 direct_spell_resolution(idx, spell, PL, src): party member idx
// casts spell at PL on the target record src (8 dwords). It acknowledges
// (0x52fe80: voice 0x52e690 unless 0x683f95/0x683f96 is set), fills slot
// idx's action block Q = [0x685178] + idx*0x106 (+1 = 7, +5 spell, +9 = -1,
// +0x15 PL, +0x19 = 0, +0x1d the target copy), resolves the cast through
// 0x4fa4d0 (out = the idx argument slot), records it again with 0x4f9aa0
// (+0x75 spell, +0x79 PL, +0x7d = 0, +0x81 target copy), applies fatigue
// 0x52af50(idx, levels, 1, 0) and plays the result sound 0x408860:
// 0x64cf2c (spell 0x17 on success with target item byte +6 set), 0x64c664
// (other success) or 0x6193b0 (result not 1). It returns 0x4fa4d0's result.
// 0x4fa4d0 is an address stub in the case: Emu replays its result and out
// value from case inputs, F runs charCast (n_4fa4d0.go) on the same world.
// 0x52af50 is replayed in Emu and run as characterFatigueApplyNode in F
// (spcCallees); its eax is ignored. 0x408860 / 0x52e690 are 排除 stubs.

var dsrStubs = func() map[uint32]*mcaStub {
	m := make(map[uint32]*mcaStub, len(spcStubs)+len(dsrExtraStubs))
	for k, v := range spcStubs {
		m[k] = v
	}
	for k, v := range dsrExtraStubs {
		m[k] = v
	}
	return m
}()

func (w *spcWorld) directSpell(idx, spell, pl, src uint32) uint32 {
	if w.u8(0x683f95) == 0 && w.u8(0x683f96) == 0 { // 0x52fe80(idx, 0)
		w.stub(0x52e690, w.charBase(idx), w.u32(0x68c50c), 0, w.u32(0x5ed8c8), w.u32(0x5ed914))
	}
	q := w.u32(0x685178) + idx*0x106
	w.put32(q+1, 7)
	w.put32(q+5, spell)
	w.put32(q+9, 0xffffffff)
	w.put32(q+0x15, pl)
	w.put32(q+0x19, 0)
	w.copyDw(q+0x1d, src, 8)
	out := uint32(mstStackBase + 4) // the idx argument slot
	var res uint32
	if w.real {
		w.call(0x4fa4d0, idx, spell, pl, out, 0)
		res = w.charCast(idx, spell, pl, out, 0)
	} else {
		res = w.stub(0x4fa4d0, idx, spell, pl, out, 0)
	}
	w.put32(q+0x75, spell) // 0x4f9aa0(idx, spell, PL, src)
	w.put32(q+0x79, pl)
	w.put32(q+0x7d, 0)
	w.copyDw(q+0x81, src, 8)
	w.stub(0x52af50, idx, w.u32(out), 1, 0)
	msg := uint32(0x6193b0)
	if res == 1 {
		msg = 0x64c664
		if spell == 0x17 && w.u8(w.u32(src+0x1c)+6) != 0 {
			msg = 0x64cf2c
		}
	}
	w.stub(0x408860, msg, 0)
	return res
}

func dsrBody(w *mcaWorld) {
	s := &spcWorld{mcaWorld: w}
	w.tab = dsrStubs
	s.put(mstRet, 4, uint64(s.directSpell(s.arg(0), s.arg(1), s.arg(2), s.arg(3))))
}

func directSpellResolutionNode(in []int64, r Rand) []int64 {
	return mcaRun(&dsrSpec, true, dsrBody)(in, r)
}

func dsrEmu(in []int64, r Rand) []int64 { return mcaRun(&dsrSpec, false, dsrBody)(in, r) }

func init() {
	Nodes["005a6340"] = Node{Addr: "005a6340", In: dsrIn, Out: dsrOut, F: directSpellResolutionNode, Emu: dsrEmu}
}

